/bin/bash -lc "cat > /tmp/landing.css <<'EOF'
.landing {
  min-height: 100vh;
  padding: 72px 0 64px;
}

.hero,
.cta {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: 20px;
}

.landing-subtitle {
  max-width: 560px;
  margin: 0;
}

.benefits {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 16px;
  margin: 56px 0;
}

.benefit-card {
  padding: 24px;
}

.benefit-card h2 {
  margin: 0 0 8px;
}

.benefit-card p {
  margin: 0;
}

.cta {
  align-items: center;
  padding: 32px;
  border: 1px solid var(--g-color-line-generic);
  border-radius: 16px;
  text-align: center;
}

.cta h2 {
  margin: 0;
}

@media (max-width: 720px) {
  .landing {
    padding: 48px 0;
  }

  .benefits {
    grid-template-columns: 1fr;
    margin: 40px 0;
  }
}
EOF
cp /tmp/landing.css src/App.css
npm run build"
